import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy local database reference","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy local database reference","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.md"}'),o={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.md"};function i(n,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<div><h1 id="chainy-local-database-reference">Chainy local database reference<a class="header-anchor" href="#chainy-local-database-reference" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Owner: Christian Jude Villaber. Updated October 12, 2026 from the supplied technical design.</p><p>SQLite stores data on the device. The user requested documentation adoption, not changes to the running game&#39;s database. The previous generated learners/sessions/attempts/export-table schema has been <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/design/local-schema.html">archived</a>. It must not be applied as the current design.</p><h2 id="adopted-source-model">Adopted source model<a class="header-anchor" href="#adopted-source-model" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Entity</th><th>Purpose</th><th>Fields shown in the supplied dictionary</th></tr></thead><tbody><tr><td>User</td><td>Local learner/staff profile</td><td>user_id, student_code, username, age, isTeacher</td></tr><tr><td>Module</td><td>Group of learning content</td><td>module_id, module_name, description</td></tr><tr><td>Lesson</td><td>Lesson in a module</td><td>lesson_id, module_id, a truncated sequence field, a truncated lesson-title field</td></tr><tr><td>User_Progress</td><td>Current progress for a user and lesson</td><td>progress_id, user_id, lesson_id, score, attempts, is_completed, percentage</td></tr><tr><td>User_Analytics</td><td>Reported analysis records linked to progress</td><td>analytics_id, user_id, lesson_id, score, attempts, percentage</td></tr></tbody></table><p>User and Lesson relate to User_Progress; Module contains Lessons. User_Analytics is shown connected to progress, but the source does not supply a reliable implemented key design.</p><figure class="diagram"><div class="mermaid-source"><pre>erDiagram
  User ||--o{ User_Progress : has
  Module ||--o{ Lesson : contains
  Lesson ||--o{ User_Progress : tracks
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>The diagram deliberately shows only relationships clearly described in the source. Christian must confirm the analytics relationship from the actual schema.</p><h2 id="field-dictionary">Field dictionary<a class="header-anchor" href="#field-dictionary" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Field(s)</th><th>Source declaration</th><th>Meaning / unresolved detail</th></tr></thead><tbody><tr><td>User.user_id</td><td>Type not shown; “likely INTEGER,” presumed primary key</td><td>Actual type and primary-key definition must come from the game schema</td></tr><tr><td>User.student_code</td><td>INTEGER</td><td>Conflicts with Part VI&#39;s proposed alphanumeric input validation</td></tr><tr><td>User.username</td><td>VARCHAR(30)</td><td>Source calls it name or login name; decide whether this is a nickname and whether it is needed</td></tr><tr><td>User.age</td><td>INTEGER</td><td>Confirm research need and permitted range with Sean; no birth date is requested</td></tr><tr><td>User.isTeacher</td><td>BOOLEAN</td><td>Local role marker, not proof of staff identity or access authorization</td></tr><tr><td>Module.module_id</td><td>INTEGER primary key</td><td>Module identifier</td></tr><tr><td>Module.module_name / description</td><td>VARCHAR(255) / TEXT(65535)</td><td>Name and explanation</td></tr><tr><td>Lesson.lesson_id / module_id</td><td>INTEGER primary key / foreign key</td><td>Lesson identity and owning module</td></tr><tr><td>Lesson.sequence field / title field</td><td>INTEGER / VARCHAR(255); names truncated in source</td><td>Do not turn guessed spellings into a migration</td></tr><tr><td>User_Progress.progress_id</td><td>INTEGER primary key</td><td>Progress row identifier</td></tr><tr><td>User_Progress.user_id / lesson_id</td><td>INTEGER foreign keys</td><td>Existing user and lesson</td></tr><tr><td>User_Progress.score / attempts / percentage</td><td>INTEGER</td><td>Latest/best/cumulative score, attempt unit and percentage formula unspecified</td></tr><tr><td>User_Progress.is_completed</td><td>BOOLEAN</td><td>Completion rule/default unspecified</td></tr><tr><td>User_Analytics.analytics_id</td><td>INTEGER primary key</td><td>Analysis row identifier</td></tr><tr><td>User_Analytics remaining fields</td><td>INTEGER; linked to progress fields in the source</td><td>Snapshot, summary or derived report is not defined</td></tr></tbody></table><h2 id="decisions-before-schema-changes">Decisions before schema changes<a class="header-anchor" href="#decisions-before-schema-changes" aria-label="Link to this section">​</a></h2><p>Christian resolves these on CH-04, with Sean reviewing evaluation needs:</p><ol><li>Export the actual table definitions and confirm full names, types, keys and schema version.</li><li>Choose one learner-code format. Recommendation: TEXT if codes allow letters or meaningful leading zeroes. Do not silently convert existing records.</li><li>Define one score rule and one meaning for attempts; state the percentage denominator and rounding. A maximum score is mentioned in validation but not defined in the dictionary.</li><li>Enforce one current progress row per user/lesson if that is the intended model. Decide whether earlier attempts must be retained separately for the approved study.</li><li>Define User_Analytics. Recommendation: derive reports from authoritative records where possible instead of copying mutable scores into a second table. A historical snapshot needs an explicit identifier and meaning.</li><li>Identify the fields that support the promised session/checkpoint behavior. Decide a safe resume point; avoid saving transient animation state.</li><li>Confirm whether username/age are necessary. Keep identity maps and raw learner data outside repositories and issues.</li></ol><p>These recommendations do not override the Tech Lead&#39;s schema. The supplied dictionary is not detailed enough to safely manufacture SQL or a migration.</p><h2 id="required-validation-and-save-behavior">Required validation and save behavior<a class="header-anchor" href="#required-validation-and-save-behavior" aria-label="Link to this section">​</a></h2><p>The source requires unique non-null keys, valid parent relationships, nonblank required text, valid ages/Booleans, ordered lessons, unique current progress and bounded scores. Christian must implement these in the actual schema/application.</p><p>SQLite does not enforce the length in VARCHAR(30), and Boolean values use integer storage. Explicit validation is needed. See <a href="https://www.sqlite.org/datatype3.html">SQLite types</a>.</p><p>Enable and verify foreign-key enforcement on each database connection. See <a href="https://www.sqlite.org/foreignkeys.html">SQLite foreign keys</a>.</p><p>Use bound query parameters. Save related score/completion changes together, and return success only after commit; failed writes must preserve the previous save. See <a href="https://www.sqlite.org/lang_transaction.html">SQLite transactions</a>.</p><p>A repeated completion/save request must not inflate attempts or award progress twice. Christian chooses the smallest repeat-safe approach consistent with the actual schema. Do not retrofit the old event/export framework without a demonstrated need.</p><h2 id="lifecycle-and-collection">Lifecycle and collection<a class="header-anchor" href="#lifecycle-and-collection" aria-label="Link to this section">​</a></h2><p>Create/select profiles locally; isolate them on shared devices. A code entered on another phone does not restore records. Keep a supported checkpoint for resume, with clear feedback after interruption.</p><p>Before any real database change, record the existing version, back up consistently, test the change using synthetic data and verify that an in-place app update preserves records. This document authorizes no deletion or migration.</p><p>Teacher collection is a separate workflow in the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/offline-data-plan.html">offline data plan</a>. SQLite storage does not upload records automatically. Research exports should contain only approved fields and enough identifiers to avoid counting the same result twice.</p><h2 id="acceptance-evidence">Acceptance evidence<a class="header-anchor" href="#acceptance-evidence" aria-label="Link to this section">​</a></h2><p>CH-04 needs: actual schema + two-profile isolation + result save/reload + retry without duplicate counting + failed-save recovery. CH-14 adds interrupted play and in-place update checks on the beta device. Record build, device, expected result, actual result and reviewer.</p></div>`,1)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
